import React,{useEffect,useState} from 'react';
import {ChevronRight,Maximize2,Save,Link2,SlidersHorizontal,UserRound,BookOpen} from 'lucide-react';
import type {HostAdapter} from '../host/adapter';
import type {Resource,Data} from '../host/types';
import {clone} from '../host/model';
import {useHost,useTask,SearchBox,Notice,Empty,Field,IconButton,Row,NativeLink} from '../ui/common';
export const labels:Record<Resource,string>={connection:'连接',preset:'预设',world:'世界书',persona:'用户设定'};
export default function Resources({host,kind,initial,deep,onDeep}:{host:HostAdapter,kind:Exclude<Resource,'world'>,initial?:string,deep?:boolean,onDeep?:(id:string)=>void}){
 const snap=useHost(host),task=useTask(),[query,setQuery]=useState(''),[id,setId]=useState(initial||snap.current[kind]||snap.resources[kind][0]?.id||'');
 const items=snap.resources[kind].filter(x=>`${x.name} ${x.detail}`.toLowerCase().includes(query.toLowerCase())),current=snap.resources[kind].find(x=>x.id===id);
 return <div className={`wb-resources ${deep?'is-deep':''}`}><div className="wb-resource-list"><SearchBox value={query} onChange={setQuery} placeholder={`搜索${labels[kind]}`}/>{items.map((x,i)=><React.Fragment key={x.id}>{kind==='connection'&&(i===0||items[i-1].detail!==x.detail)&&<p className="wb-caption">{x.detail}</p>}<Row name={x.name} detail={kind==='connection'?x.data?.api:x.detail} active={id===x.id} onClick={()=>{const e=new Event('wb-before-close',{cancelable:true});if(window.dispatchEvent(e))setId(x.id);}}><IconButton title={`使用 ${x.name}`} disabled={snap.busy} onClick={()=>task.run(()=>host.select(kind,x.id))}><ChevronRight size={16}/></IconButton></Row></React.Fragment>)}{!items.length&&<Empty>暂无{labels[kind]}，请从原生入口创建。</Empty>}<NativeLink onClick={()=>host.native(kind)}>新建 / 导入与高级设置</NativeLink></div><div className="wb-resource-detail"><Notice error={task.error}/>{current?<><div className="wb-section-title"><h3>{current.name}</h3><span className="wb-grow"/>{onDeep&&<IconButton title="独立深度编辑" onClick={()=>onDeep(id)}><Maximize2 size={17}/></IconButton>}</div><button className="wb-primary" disabled={snap.busy} onClick={()=>task.run(()=>host.select(kind,id))}>{snap.current[kind]===id?'重新应用':'切换到此项'}</button><ResourceEditor key={`${kind}:${id}`} host={host} kind={kind} id={id} deep={deep}/></>:<Empty>选择一个条目查看详情</Empty>}</div></div>;
}
function ResourceEditor({host,kind,id,deep}:{host:HostAdapter,kind:Exclude<Resource,'world'>,id:string,deep?:boolean}){
 const task=useTask(),[base,setBase]=useState<Data|null>(null),[draft,setDraft]=useState<Data|null>(null),[json,setJson]=useState(''),[message,setMessage]=useState('');
 useEffect(()=>{try{const data=kind==='preset'?host.presetData(id):kind==='persona'?host.personaData(id):clone(host.snapshot().resources.connection.find(x=>x.id===id)?.data??{});setBase(clone(data));setDraft(clone(data));setJson(JSON.stringify(data,null,2));}catch(e){task.setError(String(e));}},[kind,id]);
 const dirty=Boolean(base)&&(kind==='preset'?json!==JSON.stringify(base,null,2):JSON.stringify(base)!==JSON.stringify(draft));
 useEffect(()=>{const guard=(e:Event)=>{if(dirty&&!confirm('有未保存修改，放弃这些修改？'))e.preventDefault();};const unload=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue='';}};window.addEventListener('wb-before-close',guard);window.addEventListener('beforeunload',unload);return()=>{window.removeEventListener('wb-before-close',guard);window.removeEventListener('beforeunload',unload);};},[dirty]);
 if(!draft||!base)return <Notice error={task.error}/>;
 const change=(key:string,value:any)=>{setDraft({...draft,[key]:value});setMessage('');};
 return <div className="wb-fields"><Notice error={task.error}/>{kind==='connection'?<>
  <Field label="连接名称"><input value={draft.name??''} onChange={e=>change('name',e.target.value)}/></Field><Field label="模型"><input value={draft.model??''} onChange={e=>change('model',e.target.value)}/></Field><Field label="模型分组"><input value={host.prefs().groups[id]??''} placeholder={draft.model||'按模型自动分组'} onChange={e=>host.preference({groups:{...host.prefs().groups,[id]:e.target.value}})}/></Field><div className="wb-note">API、地址及密钥通过原生连接面板编辑。这里沿用连接配置中的凭据引用。</div><NativeLink onClick={()=>host.native('connection')}>打开原生连接配置</NativeLink>
 </>:kind==='persona'?<><Field label="用户名称"><input value={draft.name??''} onChange={e=>change('name',e.target.value)}/></Field><Field label="说明标题"><input value={draft.title??''} onChange={e=>change('title',e.target.value)}/></Field><Field label="用户描述"><textarea rows={10} value={draft.description??''} onChange={e=>change('description',e.target.value)}/></Field><NativeLink onClick={()=>host.native('persona')}>头像、锁定与注入设置</NativeLink></>:<>
 <div className="wb-note">完整预设以 JSON 编辑，保留未知字段。提示词拖动排序等操作可进入原生编辑器。</div>{deep?<Field label="预设 JSON"><textarea className="wb-code wb-preset-json" value={json} onChange={e=>{setJson(e.target.value);setMessage('');}}/></Field>:<dl className="wb-summary">{Object.entries(base).filter(([,v])=>typeof v==='number'||typeof v==='boolean').slice(0,8).map(([k,v])=><React.Fragment key={k}><dt>{k}</dt><dd>{String(v)}</dd></React.Fragment>)}</dl>}<p className="wb-caption">自动绑定</p>{(['connection','model'] as const).map(scope=><label key={scope}><input type="checkbox" disabled={scope==='connection'&&!host.snapshot().current.connection} checked={host.prefs().bindings[host.bindingKey(scope)]===id} onChange={e=>{const bindings={...host.prefs().bindings};e.target.checked?bindings[host.bindingKey(scope)]=id:delete bindings[host.bindingKey(scope)];host.preference({bindings});}}/>绑定当前{scope==='connection'?'连接':'模型'}</label>)}<small>连接绑定优先于模型绑定；不绑定时沿用原生行为。</small><NativeLink onClick={()=>host.native('preset')}/></>}
 <div className="wb-editor-footer"><small>{dirty?'未保存修改':message}</small><span className="wb-grow"/><button className="wb-primary" disabled={!dirty||task.busy} onClick={()=>task.run(async()=>{let next=draft;if(kind==='preset'){const parsed=JSON.parse(json);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error('预设必须是 JSON 对象');next=await host.savePreset(id,base,parsed);}else if(kind==='persona')next=await host.savePersona(id,base,draft);else await host.saveProfile(id,base,{name:draft.name,model:draft.model});setBase(clone(next));setDraft(clone(next));setJson(JSON.stringify(next,null,2));setMessage(kind==='preset'?'已保存':'已交由酒馆保存设置');})}><Save size={15}/>保存</button></div>
 </div>;
}
